// Log level priority mapping
const LOG_LEVEL_PRIORITY = {
    debug: 0,
    info: 1,
    warn: 2,
    error: 3,
};
/**
 * Custom logger backend that supports LOG_LEVEL environment variable filtering
 */
class FilteredLoggerBackend {
    minLevel;
    constructor() {
        // Get log level from environment variable, default to "info"
        const envLevel = process.env.LOG_LEVEL?.toLowerCase();
        this.minLevel =
            envLevel && envLevel in LOG_LEVEL_PRIORITY ? envLevel : "info";
    }
    log(_ctx, entry) {
        // Skip logs below the minimum level
        if (LOG_LEVEL_PRIORITY[entry.level] < LOG_LEVEL_PRIORITY[this.minLevel]) {
            return;
        }
        // Format the log output
        const elements = [
            entry.level.toUpperCase(),
            entry.message,
        ];
        if (entry.metadata && Object.keys(entry.metadata).length > 0) {
            elements.push(JSON.stringify(entry.metadata));
        }
        if (entry.error) {
            const error = entry.error instanceof Error
                ? entry.error
                : new Error(String(entry.error));
            elements.push(error);
        }
        // Output to appropriate console method
        if (entry.level === "error") {
            console.error(...elements);
        }
        else {
            console.log(...elements);
        }
    }
}


